const pptxgen = require('pptxgenjs');

const SLIDE_W = 10;
const SLIDE_H = 5.625;

function addBg(slide, color = 'F8FAFC') {
  slide.background = { color };
}

function addPage(slide, num, theme, dark = false) {
  slide.addText(String(num).padStart(2, '0'), {
    x: 9.35, y: 5.14, w: 0.38, h: 0.16,
    fontFace: theme.fontBody, fontSize: 7.5,
    color: dark ? theme.textOnDark : theme.muted,
    align: 'right', margin: 0,
  });
}

function addTitle(slide, title, subtitle, theme, opts = {}) {
  const dark = !!opts.dark;
  slide.addText(title, {
    x: opts.x ?? 0.48, y: opts.y ?? 0.34, w: opts.w ?? 8.9, h: opts.h ?? 0.45,
    fontFace: theme.fontHead, fontSize: opts.fontSize ?? 22,
    bold: true, color: dark ? theme.textOnDark : theme.text,
    margin: 0, breakLine: false, fit: 'shrink',
  });
  if (subtitle) {
    slide.addText(subtitle, {
      x: opts.x ?? 0.5, y: (opts.y ?? 0.34) + 0.5, w: opts.sw ?? 8.7, h: 0.25,
      fontFace: theme.fontBody, fontSize: opts.subtitleSize ?? 8.5,
      color: dark ? theme.textSubtleDark : theme.muted,
      margin: 0, fit: 'shrink',
    });
  }
}

function addKicker(slide, text, x, y, w, theme, dark = false) {
  slide.addText(text.toUpperCase(), {
    x, y, w, h: 0.16, fontFace: theme.fontBody, fontSize: 6.8,
    bold: true, charSpace: 1.1,
    color: dark ? theme.accent2 : theme.accent, margin: 0,
  });
}

function card(slide, x, y, w, h, theme, opts = {}) {
  slide.addShape(pptxgen.ShapeType.roundRect, {
    x, y, w, h,
    rectRadius: 0.08,
    fill: { color: opts.fill || 'FFFFFF', transparency: opts.transparency ?? 0 },
    line: { color: opts.line || theme.line, transparency: opts.lineTransparency ?? 0, width: opts.lineWidth ?? 0.7 },
    shadow: opts.shadow ? { type: 'outer', color: '0F172A', opacity: 0.08, blur: 1, angle: 45, distance: 1 } : undefined,
  });
}

function pill(slide, text, x, y, w, theme, opts = {}) {
  slide.addShape(pptxgen.ShapeType.roundRect, {
    x, y, w, h: opts.h ?? 0.25,
    rectRadius: 0.08,
    fill: { color: opts.fill || theme.accent },
    line: { color: opts.fill || theme.accent, transparency: 100 },
  });
  slide.addText(text, {
    x, y: y + 0.055, w, h: 0.12,
    fontFace: theme.fontBody, fontSize: opts.fontSize ?? 6.8,
    bold: true, color: opts.color || 'FFFFFF', align: 'center', margin: 0, fit: 'shrink',
  });
}

function addBullets(slide, bullets, x, y, w, theme, opts = {}) {
  const dark = !!opts.dark;
  const runs = [];
  bullets.forEach((b, idx) => {
    runs.push({ text: `${b}\n`, options: { bullet: { type: 'bullet' }, breakLine: idx < bullets.length - 1 } });
  });
  slide.addText(runs, {
    x, y, w, h: opts.h ?? 1.6,
    fontFace: theme.fontBody, fontSize: opts.fontSize ?? 10.2,
    color: dark ? theme.textSubtleDark : theme.text,
    paraSpaceAfterPt: opts.spaceAfter ?? 6,
    breakLine: false, fit: 'shrink',
    margin: 0.02, hanging: 3,
  });
}

function metric(slide, value, label, x, y, w, theme, opts = {}) {
  const dark = !!opts.dark;
  slide.addText(value, {
    x, y, w, h: 0.34, fontFace: theme.fontHead, fontSize: opts.valueSize ?? 21,
    bold: true, color: opts.color || (dark ? theme.accent2 : theme.accent),
    margin: 0, align: opts.align || 'left', fit: 'shrink',
  });
  slide.addText(label, {
    x, y: y + 0.38, w, h: 0.24, fontFace: theme.fontBody, fontSize: opts.labelSize ?? 7.2,
    color: dark ? theme.textSubtleDark : theme.muted,
    margin: 0, align: opts.align || 'left', fit: 'shrink',
  });
}

function connector(slide, x1, y1, x2, y2, theme, opts = {}) {
  slide.addShape(pptxgen.ShapeType.line, {
    x: x1, y: y1, w: x2 - x1, h: y2 - y1,
    line: { color: opts.color || theme.accent, width: opts.width || 1.2, beginArrowType: 'none', endArrowType: 'triangle' },
  });
}

function imageContain(slide, path, x, y, w, h, opts = {}) {
  slide.addImage({ path, x, y, w, h, sizing: { type: 'contain', x, y, w, h }, transparency: opts.transparency });
}

function addFooterNote(slide, note, theme, dark = false) {
  slide.addText(note, {
    x: 0.5, y: 5.08, w: 8.2, h: 0.2, fontFace: theme.fontBody, fontSize: 6.6,
    color: dark ? theme.textSubtleDark : theme.muted, margin: 0, fit: 'shrink',
  });
}

module.exports = {
  SLIDE_W, SLIDE_H, addBg, addPage, addTitle, addKicker, card, pill,
  addBullets, metric, connector, imageContain, addFooterNote, pptxgen,
};
EOF

