const { addBg, addPage, addTitle, addKicker, card, pill, imageContain, connector, pptxgen } = require('./helpers');

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  addBg(slide, theme.bg);
  addTitle(slide, 'SmolVLM Architecture: Image Splitting, Pixel Shuffle, and SmolLM2 Backbone', 'A compact multimodal pipeline concatenates compressed visual embeddings with text embeddings.', theme, { fontSize: 18.5 });

  card(slide, 0.58, 1.12, 8.84, 1.42, theme, { fill: 'FFFFFF', shadow: true });
  imageContain(slide, '/app/benchmark/assets/figure_3.jpg', 0.8, 1.28, 8.4, 0.96);
  slide.addText('Figure reference: SmolVLM architecture', { x: 0.72, y: 2.28, w: 2.1, h: 0.13, fontFace: theme.fontBody, fontSize: 6.4, color: theme.muted, margin: 0 });

  const steps = [
    ['1', 'Split image', 'Images are split into sub-images before encoding.'],
    ['2', 'Encode with SigLIP', 'A SigLIP vision encoder maps patches to visual features.'],
    ['3', 'Pixel shuffle', 'Space-to-depth compression reduces visual token count.'],
    ['4', 'Project to SmolLM2', 'A linear layer maps visual features into LM input space.'],
  ];
  const xs = [0.62, 2.94, 5.26, 7.58];
  steps.forEach((s, i) => {
    card(slide, xs[i], 3.12, 1.74, 1.18, theme, { fill: i === 2 ? theme.pale : 'FFFFFF', line: i === 2 ? theme.accent : theme.line });
    slide.addShape(pptxgen.ShapeType.oval, { x: xs[i] + 0.13, y: 3.28, w: 0.34, h: 0.34, fill: { color: i === 2 ? theme.accent : theme.navy }, line: { transparency: 100 } });
    slide.addText(s[0], { x: xs[i] + 0.13, y: 3.36, w: 0.34, h: 0.1, fontFace: theme.fontBody, fontSize: 6.6, bold: true, color: 'FFFFFF', align: 'center', margin: 0 });
    slide.addText(s[1], { x: xs[i] + 0.58, y: 3.25, w: 0.95, h: 0.18, fontFace: theme.fontHead, fontSize: 9.5, bold: true, color: theme.text, margin: 0, fit: 'shrink' });
    slide.addText(s[2], { x: xs[i] + 0.15, y: 3.65, w: 1.44, h: 0.35, fontFace: theme.fontBody, fontSize: 7.1, color: theme.muted, margin: 0, fit: 'shrink' });
    if (i < 3) connector(slide, xs[i] + 1.75, 3.72, xs[i] + 2.18, 3.72, theme, { width: 1 });
  });
  addKicker(slide, 'Video path', 0.74, 4.72, 0.8, theme);
  slide.addText('Frames are sampled and processed through the same image pipeline.', { x: 1.48, y: 4.69, w: 3.3, h: 0.18, fontFace: theme.fontBody, fontSize: 8.4, color: theme.muted, margin: 0 });
  pill(slide, 'Design levers: encoder-LM balance • token compression • context scaling', 5.02, 4.58, 3.55, theme, { fill: theme.navy, fontSize: 6.5 });
  addPage(slide, 3, theme);
}
module.exports = { createSlide };
EOF

