  slide.addText(text, {
    x: x + 0.025, y: y + (opts.yPad ?? 0.055), w: w - 0.05, h: h - 0.06,
    fontFace: theme.fontBody, fontSize: opts.fontSize ?? 5.2,
    bold: opts.bold || false, color: opts.color || theme.text,
    align: opts.align || 'center', valign: 'mid', margin: 0, fit: 'shrink',
  });
}

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  addBg(slide, theme.bg);
