  let x = x0;
  headers.forEach((h, i) => { cell(slide, h, x, y0, widths[i], 0.28, theme, { fill: i < 2 ? theme.navy : theme.slate, color: 'FFFFFF', bold: true, fontSize: 5.2 }); x += widths[i]; });

  const rows = [
    ['Single-Image', 'OCRBench', '52.6%', '61.0%', '72.9%', '54.7% (Molmo-A1B-7B)'],
    ['Single-Image', 'AI2D', '46.4%', '59.2%', '70.0%', '71.0% (Molmo-A1B-7B)'],
