    ['Multi-task', 'MMStar', '34.6%', '38.3%', '46.0%', '43.1% (Molmo-A1B-7B)'],
    ['Video', 'Video-MME', '33.7%', '42.2%', '52.1%', '45.0% (InternVL2-2B)'],
    ['Video', 'MLVU', '40.6%', '47.3%', '55.2%', '48.2% (InternVL2-2B)'],
    ['Average', 'All benchmarks', '44.0%', '51.0%', '59.8%', '—'],
    ['RAM', 'batch=1', '0.8GB', '1.2GB', '4.9GB', '27.7GB (Molmo-A1B-7B)'],
  ];

  rows.forEach((r, ri) => {
    const y = y0 + 0.28 + ri * 0.25;
    const isAvg = r[0] === 'Average';
    const isRam = r[0] === 'RAM';
    const fill = isAvg ? theme.pale : isRam ? 'FFF7ED' : (ri % 2 ? 'F8FAFC' : 'FFFFFF');
    x = x0;
    r.forEach((v, ci) => {
      const highlight = (isAvg || isRam) && ci >= 2 && ci <= 4;
      cell(slide, v, x, y, widths[ci], 0.25, theme, {
        fill,
        fontSize: ci === 5 ? 4.65 : 4.95,
        bold: isAvg || isRam || (ci >= 2 && ci <= 4),
        color: highlight ? theme.accent : (isRam && ci === 5 ? theme.warning : theme.text),
        align: ci < 2 || ci === 5 ? 'left' : 'center',
        yPad: 0.048,
      });
      x += widths[ci];
    });
  });

  card(slide, 7.02, 1.03, 2.65, 1.18, theme, { fill: theme.navy, line: theme.navy, shadow: true });
  metric(slide, '0.8GB', 'SmolVLM-256M RAM', 7.28, 1.24, 1.1, theme, { dark: true, valueSize: 17, color: theme.accent2 });
  metric(slide, '27.7GB', 'Molmo-A1B-7B RAM', 8.35, 1.24, 1.08, theme, { dark: true, valueSize: 17, color: 'FFFFFF' });
  slide.addText('SmolVLM-256M also surpasses the 300× larger Idefics-80B per the paper key findings.', { x: 7.26, y: 1.95, w: 1.95, h: 0.16, fontFace: theme.fontBody, fontSize: 5.9, color: theme.textSubtleDark, margin: 0, fit: 'shrink' });

  card(slide, 7.02, 2.55, 2.65, 1.7, theme, { fill: 'FFFFFF', shadow: true });
  addKicker(slide, 'Reading the table', 7.28, 2.82, 1.1, theme);
  slide.addText('• SmolVLM-2.2B reaches 59.8% average.\n• 256M and 500M operate below 1.2GB RAM.\n• Video baselines come from InternVL2-2B; other efficient OS rows use Molmo-A1B-7B.', { x: 7.28, y: 3.1, w: 1.95, h: 0.72, fontFace: theme.fontBody, fontSize: 6.2, color: theme.text, margin: 0, fit: 'shrink', breakLine: false });
  addKicker(slide, 'Source: brief benchmark table', 0.32, 4.52, 1.55, theme);
  addPage(slide, 7, theme);
}
module.exports = { createSlide };
